<script lang="ts">
  import { Button } from "$lib/components/ui/button";
  import type { DataSourceDbEntry } from "$lib/database/datasources";
  import { DataSourceRepository, mapToDataSourceDbEntry } from "$lib/database/dataSourceRepository.svelte";

  import { Inspect } from "svelte-inspect-value";
  import Highlight from "svelte-highlight";
  import jsonHighlight from "svelte-highlight/languages/json";
  import "svelte-highlight/styles/dracula.css";

  let dataSourcesRaw = DataSourceRepository.getAllSourcesState();
  let dataSources = $derived(dataSourcesRaw.rows.map(mapToDataSourceDbEntry));

  let selectedDataSource = $state<DataSourceDbEntry | null>(null);

  function handleAdd () {
    selectedDataSource = {
      id: "" as DataSourceDbEntry["id"],
      config: {
        title: "",
        short: "",
        type: "BY_CODE",
        code: ""
      }
    };
  }

  function handleEdit (dataSource: DataSourceDbEntry) {
    selectedDataSource = { ...dataSource };
  }

  function handleDelete (dataSourceId: string) {
    DataSourceRepository.deleteSource(dataSourceId);
  }

  async function handleSubmit (e: Event) {
    e.preventDefault();

    if (!selectedDataSource) {
      return;
    }

    try {
      JSON.parse(selectedDataSource.config.code);
    } catch (e) {
      alert("Invalid JSON: " + e);
      return;
    }

    if (selectedDataSource.id) {
      DataSourceRepository.updateSource(selectedDataSource.id, selectedDataSource.config);
    } else {
      DataSourceRepository.addSource(selectedDataSource.config);
    }

    selectedDataSource = null;
  }
</script>

<Button onclick={handleAdd}>Add Data Source</Button>
<table style="border-spacing: 0.5em; border-collapse: separate;">
  <thead>
  <tr>
    <th>Title</th>
    <th>Short</th>
    <th>Type</th>
    <th>Value</th>
    <th>Actions</th>
  </tr>
  </thead>
  <tbody>
  {#each dataSources as dataSource}
    <tr>
      <td>{dataSource.config.title} </td>
      <td>
        <pre>{dataSource.config.short}</pre>
      </td>
      {#if dataSource.config.type === 'BY_CODE'}
        <td>Code</td>
        <td>
          <Highlight language={jsonHighlight} code={dataSource.config.code} />
        </td>
      {:else if dataSource.config.type === 'BY_FETCH'}
        <td>Fetch</td>
        <td>{dataSource.config.url}</td>
      {/if}
      <td>
        <Button onclick={() => handleEdit(dataSource)}>Edit</Button>
        <Button onclick={() => handleDelete(dataSource.id)}>Delete</Button>
      </td>


    </tr>
  {/each}
  </tbody>
</table>

<Inspect value={dataSources} />

{#if selectedDataSource}
  <form onsubmit={handleSubmit}>
    <label>
      Title:<br />
      <input type="text" bind:value={selectedDataSource.config.title} required />
    </label><br />
    <label>
      Short:<br />
      <input type="text" bind:value={selectedDataSource.config.short} required />
    </label>
    <!--<br />
    <label>
      Type:
      <select bind:value={selectedDataSource.type}>
        <option value="BY_CODE">By Code</option>
        <option value="BY_FETCH">By Fetch</option>
      </select>
    </label>-->
    <br />
    {#if selectedDataSource.config.type === "BY_CODE"}
      <label>
        Code:<br />
        <textarea bind:value={selectedDataSource.config.code} required></textarea>
      </label>
      <br />
    {:else if selectedDataSource.config.type === "BY_FETCH"}
      <!--  <label>
          URL:
          <input type="url" bind:value={selectedDataSource.config.url} required />
        </label>
        <br />
        <label>
          Method:
          <select bind:value={selectedDataSource.config.method}>
            <option value="GET">GET</option>
            <option value="POST">POST</option>
          </select>
        </label>
        <br />
        <label>
          Body JSON:
          <textarea bind:value={selectedDataSource.config.bodyJson}></textarea>
        </label>
        <br />-->
    {/if}
    <Button type="submit">Save</Button>
    <Button type="button" onclick={() => selectedDataSource = null}>Cancel</Button>
  </form>
{/if}


